const bars = d.nen.map(x => ({ open: x.o, high: x.h, low: x.l, close: x.c, volume: x.v }));
function rsi(values, period) {
  const out = new Array(values.length).fill(null);
  if (values.length <= period) return out;
  let avgGain = 0;
  let avgLoss = 0;
  for (let i = 1; i <= period; i++) {
    const diff = values[i] - values[i - 1];
    if (diff >= 0) avgGain += diff;
    else avgLoss -= diff;
  }
  avgGain /= period;
  avgLoss /= period;
  out[period] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
  for (let i = period + 1; i < values.length; i++) {
    const diff = values[i] - values[i - 1];
    const gain = diff > 0 ? diff : 0;
    const loss = diff < 0 ? -diff : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
    out[i] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
  }
  return out;
}
const signals = function (bars, p) {
      const r = rsi(bars.map((b) => b.close), p.period);
      return bars.map((_, i) => {
        if (i === 0 || r[i] == null || r[i - 1] == null) return 0;
        if (r[i - 1] <= p.oversold && r[i] > p.oversold) return 1;
        if (r[i - 1] >= p.overbought && r[i] < p.overbought) return -1;
        return 0;
      });
    };
const s = signals(bars, ts);
return s[s.length - 1] === 1;

